    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def is_num(x):
        return isinstance(x, int) or isinstance(x, float)

    def to_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return (int(x[0]), int(x[1]))
        if isinstance(x, dict):
            for k1, k2 in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if k1 in x and k2 in x and is_num(x.get(k1)) and is_num(x.get(k2)):
                    return (int(x.get(k1)), int(x.get(k2)))
        return None

    def iter_positions(obj):
        out = []
        if obj is None:
            return out
        p = to_pos(obj)
        if p is not None:
            out.append(p)
            return out
        if isinstance(obj, dict):
            for v in obj.values():
                out.extend(iter_positions(v))
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                out.extend(iter_positions(v))
        return out

    def find_first_pos(d, keys):
        for k in keys:
            v = d.get(k)
            p = to_pos(v)
            if p is not None:
                return p
            if isinstance(v, dict):
                for kk in ("pos", "position", "location", "loc", "xy"):
                    p = to_pos(v.get(kk))
                    if p is not None:
                        return p
        return None

    def get_role_text(d):
        for k in ("role", "agent_type", "type", "mode", "task", "scenario", "name"):
            v = d.get(k)
            if isinstance(v, str):
                return v.lower()
        return ""

    obs = observation if isinstance(observation, dict) else {}

    # Basic map/grid extraction
    grid = obs.get("grid")
    if grid is None:
        grid = obs.get("map")
    if grid is None:
        grid = obs.get("board")

    h = len(grid) if isinstance(grid, (list, tuple)) else 0
    w = len(grid[0]) if h and isinstance(grid[0], (list, tuple)) else 0

    def in_bounds(p):
        if h and w:
            return 0 <= p[0] < w and 0 <= p[1] < h
        return True

    def cell(p):
        if not (h and w and in_bounds(p)):
            return None
        return grid[p[1]][p[0]]

    blocked_vals = {"#", "X", "W", "wall", "blocked", -1, 1, 9}
    empty_vals = {None, ".", " ", 0}

    def passable(p):
        c = cell(p)
        if c is None:
            return True
        if c in blocked_vals:
            return False
        if isinstance(c, str) and c.lower() in blocked_vals:
            return False
        return True

    me = find_first_pos(obs, ("self_pos", "position", "pos", "agent_pos", "my_pos", "loc"))
    if me is None:
        me = find_first_pos(obs.get("self", {}) if isinstance(obs.get("self"), dict) else {}, ("pos", "position", "loc"))

    if me is None and isinstance(grid, (list, tuple)):
        # Heuristic scan for common self markers
        markers = {"A", "a", "@", "P", "p", "S", "s"}
        for y, row in enumerate(grid):
            if not isinstance(row, (list, tuple)):
                continue
            for x, c in enumerate(row):
                if c in markers:
                    me = (x, y)
                    break
            if me is not None:
