    if me is None:
        return [0, 0]

    role_text = get_role_text(obs)
    if not role_text and isinstance(obs.get("self"), dict):
        role_text = get_role_text(obs.get("self"))

    resource_keys = ("resources", "resource_positions", "food", "gems", "targets", "points", "objectives", "collectibles")
    enemy_keys = ("enemies", "enemy_positions", "opponents", "opponent_positions", "pursuers", "evaders", "agents")
    territory_keys = ("territory", "territories", "owned", "control", "ownership", "claimed")

    resources = []
    for k in resource_keys:
        resources.extend(iter_positions(obs.get(k)))
    enemies = []
    for k in enemy_keys:
        enemies.extend(iter_positions(obs.get(k)))
    territory = []
    for k in territory_keys:
        territory.extend(iter_positions(obs.get(k)))

    # Try nested self/enemy structures
    if isinstance(obs.get("agents"), (list, tuple)):
        for a in obs.get("agents"):
            if isinstance(a, dict):
                p = to_pos(a.get("pos")) or to_pos(a.get("position")) or to_pos(a.get("loc"))
                if p is not None:
                    txt = (a.get("team", "") if isinstance(a.get("team"), str) else "") + " " + (a.get("role", "") if isinstance(a.get("role"), str) else "") + " " + (a.get("type", "") if isinstance(a.get("type"), str) else "")
                    txt = txt.lower()
