                        else:
                            # If no labels, treat non-self agents as potentially hostile only if in pursuit_evasion.
                            if "pursuit" in role_text or "evad" in role_text:
                                enemies.append(p)

    # De-dup
    def dedup(seq):
        seen = set()
        out = []
        for p in seq:
            if p not in seen and p != me:
                seen.add(p)
                out.append(p)
        return out

    resources = dedup(resources)
    enemies = dedup(enemies)
    territory = dedup(territory)

