    def nearest_dist(points, p):
        best = 10**9
        for q in points:
            d = manhattan(p, q)
            if d < best:
                best = d
        return best

    # Determine mode
    mode = "mixed"
    if "collect" in role_text or "resource" in role_text:
        mode = "collect"
    elif "pursuit" in role_text or "pursuer" in role_text or "chase" in role_text:
        mode = "chase"
    elif "evade" in role_text or "evader" in role_text or "avoid" in role_text:
        mode = "flee"
    elif "territory" in role_text or "control" in role_text or "capture" in role_text:
        mode = "territory"

    # If we can infer threat nearby, bias away unless in chase mode.
    nearest_enemy = nearest_dist(enemies, me) if enemies else 10**9
    nearest_resource = nearest_dist(resources, me) if resources else 10**9

    best_move = (0, 0)
    best_score = -10**18

    for dx, dy in moves:
        nx, ny = me[0] + dx, me[1] + dy
        np = (nx, ny)
        if not passable(np):
            continue

        score = 0

        # Small preference for moving over staying when useful.
        if dx == 0 and dy == 0:
            score -= 1

        if resources:
            d = nearest_dist(resources, np)
            score += (50 - d * 5)

        if enemies:
            d = nearest_dist(enemies, np)
            if mode == "flee":
                score += d * 8
            elif mode == "chase":
                score += (40 - d * 6)
            else:
                # Mixed behavior: flee if close, otherwise mildly chase if far from resources.
                if nearest_enemy <= 2:
                    score += d * 6
                else:
                    score += (10 - d * 2)

        if territory:
            d = nearest_dist(territory, np)
            score += (20 - d * 2)

        # Favor unexplored/open cells on maps
        c = cell(np)
        if c in empty_vals:
            score += 2
        elif isinstance(c, str) and c not in blocked_vals:
            score += 1

        # Prefer not cornering ourselves
        if h and w:
            edge_dist = min(nx, ny, w - 1 - nx, h - 1 - ny)
            score += edge_dist

        # Role-specific small tweaks
        if mode == "collect":
            score += 0
        elif mode == "territory":
            score += 1 if c in empty_vals else 0
        elif mode == "chase":
            score += 0
        elif mode == "flee":
            score += 0

        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [clamp(best_move[0]), clamp(best_move[1])]

